import { Router } from 'express';
import { authRouter } from '../api/v1/auth/auth.route.js';
import { organizationsRouter } from '../api/v1/organizations/organizations.route.js';
import { apiKeysRouter } from '../api/v1/api-keys/api-keys.route.js';
import { auditLogsRouter } from '../api/v1/audit-logs/audit-logs.route.js';
import { healthRouter } from '../api/v1/health/health.route.js';
import { requireAuth } from '../core/auth/middleware.js';
import { categoriesRouter } from '../api/v1/categories/categories.route.js';
import { productsRouter } from '../api/v1/products/products.route.js';
import { cartRouter } from '../api/v1/cart/cart.route.js';
import { ordersRouter } from '../api/v1/orders/orders.route.js';
import { wishlistRouter } from '../api/v1/wishlist/wishlist.route.js';
import { reviewsRouter } from '../api/v1/reviews/reviews.route.js';
import { adminRouter } from '../api/v1/admin/admin.route.js';
import { supportRouter } from '../api/v1/support/support.route.js';
import { cmsRouter, registerSeoFiles } from '../api/v1/cms/cms.route.js';
import { settingsRouter } from '../api/v1/settings/settings.route.js';
export const setupRoutes = (app) => {
    const api = Router();
    app.use('/api/v1', api);
    app.use('/api/categories', categoriesRouter);
    registerSeoFiles(app);
    api.use('/health', healthRouter);
    api.use('/auth', authRouter);
    api.use('/organizations', organizationsRouter);
    api.use('/organizations/:organizationId/api-keys', requireAuth, apiKeysRouter);
    api.use('/audit-logs', auditLogsRouter);
    api.use('/categories', categoriesRouter);
    api.use('/products', productsRouter);
    app.use('/api/products', productsRouter);
    api.use('/cart', cartRouter);
    api.use('/orders', ordersRouter);
    api.use('/wishlist', wishlistRouter);
    api.use('/reviews', reviewsRouter);
    api.use('/admin/settings', settingsRouter);
    api.use('/admin', adminRouter);
    api.use('/support', supportRouter);
    api.use('/cms', cmsRouter);
};
